function editor(k,id){if(k==='sales')return saleEditor(id);if(k==='orders')return orderEditor(id);const draftKey=KEY+'-draft-'+k+'-'+(id||'new')+(db.demo?'-demo':'');let cached={};try{cached=JSON.parse(localStorage.getItem(draftKey))||{}}catch{}if(k==='products')return productEditor(id);const existing=db[k].find(x=>x.id===id),r={event:eventId,...existing,...cached};if(k==='products'&&existing&&cached.stock===undefined)r.stock=stock(db,existing);modal(`<form id="recordForm"><div class="modal-head"><div><p class="eyebrow">YOUR WORKSPACE</p><h2>${existing?'Edit':'New'} ${k==='booth'?'booth item':k.replace(/s$/,'')}</h2></div>${btn('×','close','icon','type="button" aria-label="Close"')}</div>${k==='expenses'?'<p class="notice">Event setup fees are already included in expenses. Add only additional costs here.</p>':''}<div class="form-grid">${schemas[k].map(f=>input(f,r)).join('')}</div><p class="form-error" role="alert"></p><footer>${btn('Cancel','close','secondary','type="button"')}<button class="primary" type="submit">Save ${k==='allocations'?'allocation':'record'}</button></footer></form>`);$('#recordForm').oninput=e=>{const data=new FormData(e.currentTarget),draft={};for(const f of schemas[k])draft[f.key]=f.type==='checkbox'?data.has(f.key):f.type==='number'?Number(data.get(f.key)||0):data.get(f.key);try{localStorage.setItem(draftKey,JSON.stringify(draft))}catch{}};$('#recordForm').onsubmit=e=>{e.preventDefault();try{const data=new FormData(e.target),v={...existing,id:id||uid()};for(const f of schemas[k])v[f.key]=f.type==='checkbox'?data.has(f.key):f.type==='number'?Number(data.get(f.key)||0):data.get(f.key);if(k==='products'){if(!Number.isInteger(v.stock)||!Number.isInteger(v.reserved))throw Error('Stock must use whole units.');v.stock+=sold(db,v.id)}if(k==='allocations'){if(!v.event||!v.product||!Number.isInteger(v.quantity))throw Error('Choose an event, product and whole quantity.');if(db.allocations.some(a=>a.id!==id&&a.event===v.event&&a.product===v.product))throw Error('Edit the existing allocation for this product and event.');if(v.quantity<sold(db,v.product,v.event))throw Error('Allocation cannot be below units already sold.');}if(k==='goals'&&v.target<=0)throw Error('Target must be greater than zero.');if(id)db[k]=db[k].map(x=>x.id===id?v:x);else db[k].push(v);save();localStorage.removeItem(draftKey);$('#modal').close();render();toast('Saved to your workspace')}catch(err){$('.form-error').textContent=err.message}}}
