function saleEditor(id){if(db.returns.some(r=>r.sale===id))return toast('This refunded sale is locked. Its original record is preserved.');if(!db.products.length)return toast('Add your first product before recording a sale.');const old=db.sales.find(x=>x.id===id);let draft=old?structuredClone(old):{date:today(),time:new Date().toTimeString().slice(0,5),event:eventId,payment:'Card',discount:0,lines:[]};modal(`<form id="saleForm"><div class="modal-head"><div><p class="eyebrow">MARKET DAY, MADE SIMPLE</p><h2>${id?'Edit sale':'Quick sale'}</h2></div>${btn('×','close','icon','type="button" aria-label="Close"')}</div><div class="form-grid">${[F('date','Date','date'),F('time','Time','time'),eventField,F('customer','Customer','customer'),F('payment','Payment method'),F('discount','Discount amount','number')].map(f=>input(f,draft)).join('')}</div><div class="product-picks">${db.products.map(p=>`<button type="button" class="pick" data-pick="${p.id}"><b>${esc(p.name)}</b><span>${money(p.price)} · ${stock(db,p)} available</span></button>`).join('')}</div><div id="saleLines"></div><div class="form-grid">${input(F('notes','Notes','textarea'),draft)}${input(F('override','Allow stock / allocation override','checkbox'),draft)}</div><p class="form-error" role="alert"></p><footer><strong id="saleTotal"></strong><button class="primary" type="submit">${id?'Save changes':'Record sale'}</button></footer></form>`);function lines(){ $('#saleLines').innerHTML=draft.lines.map((l,i)=>`<div class="sale-line"><b>${esc(l.name)}</b><label>Qty<input aria-label="Quantity" type="number" min="1" step="1" data-qty="${i}" value="${l.qty}"></label><label>Price<input aria-label="Price" type="number" min="0" step="0.01" data-price="${i}" value="${l.price}"></label><button type="button" data-rmline="${i}" aria-label="Remove product">×</button></div>`).join('');calc()}function calc(){draft.discount=Number($('#saleForm [name=discount]').value);$('#saleTotal').textContent='Total '+money(total(draft))}$('#saleForm').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pick){const p=db.products.find(p=>p.id===b.dataset.pick),line=draft.lines.find(l=>l.product===p.id);if(line)line.qty++;else draft.lines.push({product:p.id,name:p.name,category:p.category,price:p.price,cost:unitCost(db,p),qty:1});lines()}if(b.dataset.rmline!==undefined){draft.lines.splice(Number(b.dataset.rmline),1);lines()}};$('#saleForm').oninput=e=>{if(e.target.dataset.qty!==undefined)draft.lines[e.target.dataset.qty].qty=Number(e.target.value);if(e.target.dataset.price!==undefined)draft.lines[e.target.dataset.price].price=Number(e.target.value);calc()};$('#saleForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);for(const k of ['date','time','event','customer','payment','notes'])draft[k]=f.get(k);draft.override=f.has('override');prepareSale(db,draft);validateSale(db,draft,id);draft.id=id||uid();if(id)db.sales=db.sales.map(s=>s.id===id?draft:s);else db.sales.push(draft);save();$('#modal').close();render();toast('Sale saved. Stock and profit updated.')}catch(err){$('.form-error').textContent=err.message}};lines()}
function kpis(items){return `<div class="kpis">${items.map(([label,value,note])=>`<article class="kpi"><span>${label}</span><strong>${value}</strong><small>${note||'From your saved records'}</small></article>`).join('')}</div>`}
function bars(title,data,moneyValues=true){const max=Math.max(1,...data.map(x=>Math.abs(x[1])));return `<article class="panel"><div class="panel-title"><h3>${title}</h3><span class="tiny">SAVED DATA</span></div>${data.length?`<div class="bars">${data.map(([label,v])=>`<div><div class="bar-label"><span>${esc(label)}</span><b>${moneyValues?money(v):Number(v).toFixed(0)}</b></div><div class="bar-track"><i style="width:${Math.max(1,Math.abs(v)/max*100)}%;background:${v<0?'var(--terra)':'var(--accent)'}"></i></div></div>`).join('')}</div>`:empty('A little more data, a little more insight.')}</article>`}
function eventCard(e){const m=metrics(db,e.id);return `<article class="event-card">${e.image?`<img src="${esc(e.image)}" alt="${esc(e.name)}" loading="lazy">`:`<div class="event-art"><span>${esc(new Date(e.date+'T12:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}))}</span><small>THE MAKER’S CALENDAR</small></div>`}<div class="event-body"><div class="row"><span class="badge">${esc(e.status)}</span><small>Booth ${esc(e.boothNumber||'—')}</small></div><h3>${esc(e.name)}</h3><p>${esc(e.venue||e.city||'Location to be confirmed')}</p><div class="row"><span>Sales goal <b>${money(e.salesGoal)}</b></span><span>Packed <b>${done('packing',e.id)}%</b></span></div>${progress(done('packing',e.id))}<div class="row">${btn('Open event ↗','open-event','text',`data-id="${e.id}"`)}${btn('Edit','edit','text',`data-kind="events" data-id="${e.id}"`)}</div></div></article>`}
function checklist(k,rows){return rows.length?`<div class="checklist">${rows.map(r=>`<div><input type="checkbox" aria-label="Complete ${esc(r.name||r.title)}" data-check="${k}" data-id="${r.id}" ${r.completed||r.status==='Done'?'checked':''}><span class="${r.completed||r.status==='Done'?'checked':''}">${esc(r.name||r.title)}<small>${esc(r.category||r.due||'')}${r.quantity?' · ×'+r.quantity:''}</small></span>${btn('Edit','edit','text',`data-kind="${k}" data-id="${r.id}"`)}</div>`).join('')}</div>`:empty('Everything starts with one small step.',btn('Add item','add','secondary',`data-kind="${k}"`))}
function dashboard(){
 const m=metrics(db,'',dashboardMonth+'-01',dashboardMonth+'-31'),up=db.events.filter(e=>e.date>=today()&&!['Cancelled','Declined','Completed'].includes(e.status)).sort((a,b)=>a.date.localeCompare(b.date)),next=up[0],low=db.products.filter(p=>stock(db,p)<=p.minStock);
 const recent=[...db.sales].sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||''))).slice(0,4);
 const packed=next?db.packing.filter(p=>p.event===next.id):[];
 const cats={};db.sales.filter(s=>s.date.startsWith(dashboardMonth)).forEach(s=>s.lines.forEach(l=>cats[l.category||'Other']=(cats[l.category||'Other']||0)+l.qty));db.returns.filter(r=>r.date.startsWith(dashboardMonth)).forEach(r=>{const l=db.sales.find(s=>s.id===r.sale)?.lines[r.line];if(l)cats[l.category||'Other']=(cats[l.category||'Other']||0)-r.qty});
 return `<div class="heading dashboard-heading"><div><h1>A season with intention.</h1><p>Your markets, your making, your next chapter.</p></div>${btn('+ &nbsp; Record sale','add','primary','data-kind="sales"')}</div>
 <div class="kpis studio-kpis">${[['Upcoming markets',up.length,'Events'],['Revenue',money(m.revenue),'Sales'],['Net profit',money(m.net),'Profit'],['Ready for market',inventoryReady(next?.id)+'%','Inventory']].map(([label,value,symbol])=>`<article class="kpi"><span>${label}</span><strong>${value}</strong>${icon(symbol,26)}</article>`).join('')}</div>
 <p class="period-caption">${esc(new Date(dashboardMonth+'-01T12:00').toLocaleDateString('en-US',{month:'long',year:'numeric'}))} · ${db.demo?'Sample business':'Your saved records'}<span>Market count and readiness reflect upcoming events.</span></p>
 <div class="studio-dashboard">
 ${renderInsights(db,dashboardMonth+'-01',dashboardMonth+'-31',money,{compact:true})}
 <article class="panel next"><h3>Next market</h3>${next?nextMarket(next):empty('No markets yet.',btn('Add your first event','add','primary','data-kind="events"'))}</article>
 <article class="panel recent-panel"><div class="panel-title"><h3>Recent sales</h3>${btn('View all →','nav','text','data-page="sales"')}</div>${recentSales(recent)}</article>
 <article class="panel packing-panel"><div class="panel-title"><h3>Pack with intention</h3>${btn('View all →','nav','text','data-page="packing"')}</div>${checklist('packing',packed.slice(0,4))}${packed.length>4?`<small>${packed.length-4} more items in your event checklist</small>`:''}</article>
 ${inventoryInsights(db,money)}
 </div>
 <div class="quick-actions supplementary-actions">${['Event','Product','Expense','Task'].map(x=>btn('+ '+x,'add','secondary',`data-kind="${x.toLowerCase()}s"`)).join('')}</div>
 <div class="dashboard-extras"><article class="panel"><h3>Today’s tasks</h3>${checklist('tasks',db.tasks.filter(t=>t.due<=today()&&t.status!=='Done'))}</article><article class="panel"><h3>Booth checklist</h3>${checklist('booth',db.booth.filter(p=>p.event===next?.id).slice(0,5))}</article><article class="panel"><h3>Coming up</h3>${deadlines().filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5).map(x=>`<button class="deadline" data-action="related" data-kind="${x.kind}" data-id="${x.id}"><span>${esc(x.label)}</span><small>${esc(x.date)}</small></button>`).join('')||'<p>No upcoming deadlines or follow-ups.</p>'}</article>${bars('Categories · net units',Object.entries(cats),false)}<article class="panel"><h3>Low stock</h3>${low.map(p=>`<button class="deadline" data-action="edit" data-kind="products" data-id="${p.id}"><span>${esc(p.name)}</span><small>${stock(db,p)} left · Minimum ${p.minStock}</small></button>`).join('')||'<p>Your shelves are in good shape.</p>'}</article>${bars('Revenue vs profit',(m.transactions||m.refunds||m.expenses)?[['Revenue',m.revenue],['Gross profit',m.gross],['Net profit',m.net]]:[])}</div>`;
}
function seasonChart(){
 const weeks=marketWeeks(db,dashboardMonth),hasData=weeks.some(w=>w.revenue||w.costs);
 const raw=Math.max(1,...weeks.flatMap(w=>[w.revenue,w.costs])),step=Math.pow(10,Math.floor(Math.log10(raw))),max=Math.ceil(raw/step)*step;
 return `<article class="panel season-panel"><div class="panel-title"><h3>Your market season</h3><div class="chart-legend"><span><i></i>Revenue</span><span><i class="cost-key"></i>Costs</span></div></div>${hasData?`<div class="column-chart" role="group" aria-label="Weekly revenue and total costs for ${dashboardMonth}. Exact values are available below."><div class="chart-axis">${[1,.75,.5,.25,0].map(p=>`<span>${money(max*p)}</span>`).join('')}</div><div class="chart-plot"><div class="chart-guides">${[1,2,3,4,5].map(()=>'<i></i>').join('')}</div><div class="chart-columns" style="grid-template-columns:repeat(${weeks.length},1fr)">${weeks.map(w=>`<div class="chart-week"><div class="column-pair"><button class="chart-column revenue-column" style="height:${w.revenue/max*100}%" data-action="chart-week" data-from="${w.from}" data-to="${w.to}" aria-label="${w.label} revenue ${money(w.revenue)}. Open analysis." title="${w.label}: revenue ${money(w.revenue)}"></button><button class="chart-column cost-column" style="height:${w.costs/max*100}%" data-action="chart-week" data-from="${w.from}" data-to="${w.to}" aria-label="${w.label} costs ${money(w.costs)}. Open analysis." title="${w.label}: COGS and expenses ${money(w.costs)}"></button></div><span>${w.label}</span></div>`).join('')}</div></div></div><details class="chart-values"><summary>View exact figures</summary><div class="table-wrap"><table><tr><th>Week</th><th>Revenue</th><th>Costs</th><th>Net profit</th></tr>${weeks.map(w=>`<tr><td>${w.label}</td><td>${money(w.revenue)}</td><td>${money(w.costs)}</td><td>${money(w.revenue-w.costs)}</td></tr>`).join('')}</table></div><p>Costs include product costs, event fees and additional expenses.</p></details>`:empty('Your next chapter starts with a sale.',btn('Record your first sale','add','primary','data-kind="sales"'))}</article>`;
}
function nextMarket(e){const items=db.packing.filter(p=>p.event===e.id),count=items.filter(p=>p.completed).length;return `${e.image?`<img class="next-market-photo" src="${esc(e.image)}" alt="${esc(e.name)}" loading="lazy">`:`<div class="event-art"><span>${esc(new Date(e.date+'T12:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}))}</span><small>YOUR NEXT MARKET</small></div>`}<div class="next-market-heading"><h3>${esc(e.name)}</h3><span class="badge">${esc(e.status)}</span></div><p class="market-location">${esc(new Date(e.date+'T12:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}))} · ${esc(e.venue||e.city||'Location to be confirmed')}</p><span class="packing-label">Packing progress</span><div class="packing-ratio">${progress(done('packing',e.id))}<span>${count} / ${items.length}</span></div>${btn('Open event &nbsp; →','open-event','text',`data-id="${e.id}"`)}`}
function recentSales(rows){return rows.length?`<div class="table-wrap"><table class="recent-sales"><thead><tr><th>Product</th><th>Qty</th><th>Payment</th><th>Total</th></tr></thead><tbody>${rows.map(s=>{const p=db.products.find(p=>p.id===s.lines[0]?.product);return `<tr><td><button class="sale-product" data-action="edit" data-kind="sales" data-id="${s.id}">${p?.image?`<img src="${esc(p.image)}" alt="" loading="lazy">`:`<span class="thumbnail-fallback">${icon('Products',22)}</span>`}<span>${esc(s.lines.map(l=>l.name).join(', '))}<small>${esc(s.date)}</small></span></button></td><td>${s.lines.reduce((a,l)=>a+l.qty,0)}</td><td>${esc(s.payment)}</td><td>${money(total(s))}</td></tr>`}).join('')}</tbody></table></div>`:empty('Your first sale is a fresh beginning.',btn('Record a sale','add','primary','data-kind="sales"'))}
function inventoryReady(e){if(!e)return 0;const rows=production(db,e);return rows.length?Math.round(rows.filter(r=>r.missing===0).length/rows.length*100):0}
function salesTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Event</th><th>Payment</th><th>Total</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.lines.map(l=>l.name+' ×'+l.qty).join(', '))}</b><small>${esc(s.date)} · ${esc(s.time)}</small></td><td>${esc(name('events',s.event))}</td><td>${esc(s.payment)}</td><td>${money(total(s))}</td><td>${actions('sales',s)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your first sale is a fresh beginning.',btn('Record a sale','add','primary','data-kind="sales"'))}
const actions=(k,r)=>k==='sales'?btn('Return','return','text',`data-id="${r.id}"`)+(!db.returns.some(x=>x.sale===r.id)?btn('Edit','edit','text',`data-kind="sales" data-id="${r.id}"`):'<span class="badge">Refund recorded</span>'):`${btn('Edit','edit','text',`data-kind="${k}" data-id="${r.id}"`)}${btn('Delete','delete','text danger',`data-kind="${k}" data-id="${r.id}"`)}`;
function toolbar(k){const opts=[...new Set(db[k].map(r=>r.status||r.category).filter(Boolean))];return `<div class="toolbar"><input id="search" aria-label="Search records" placeholder="Search ${k}…" value="${esc(query)}"><select id="filter" aria-label="Filter"><option value="">All categories / statuses</option>${opts.map(v=>`<option ${filter===v?'selected':''}>${esc(v)}</option>`).join('')}</select><select id="sort" aria-label="Sort"><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="date" ${sort==='date'?'selected':''}>Date / due date</option><option value="newest" ${sort==='newest'?'selected':''}>Newest first</option></select>${['events','products'].includes(k)?btn(view==='cards'?'Table view':'Card view','view'):''}${btn('+ Add '+(k==='booth'?'item':k.replace(/s$/,'')),'add','primary',`data-kind="${k}"`)}</div>`}
function filtered(k){return db[k].filter(r=>(k!=='events'||((!eventMonth||r.date?.slice(5,7)===eventMonth)&&(!eventYear||r.date?.slice(0,4)===eventYear)&&(!eventLocation||(r.city||r.venue||'')===eventLocation)&&(!eventType||r.type===eventType)))&&(!eventId||r.event===eventId)&&(!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase()))&&(!filter||(r.status||r.category)===filter)).sort((a,b)=>sort==='newest'?db[k].indexOf(b)-db[k].indexOf(a):String(sort==='date'?(a.date||a.due||a.deadline||''):(a.name||a.title||'')).localeCompare(String(sort==='date'?(b.date||b.due||b.deadline||''):(b.name||b.title||''))))}
function listing(k){const rows=filtered(k);let content='';if(k==='events'&&view==='cards')content=`<div class="cards">${rows.map(eventCard).join('')}</div>`;else if(k==='products'&&view==='cards')content=`<div class="cards">${rows.map((p,i)=>`<article class="panel product-card">${p.image?`<img class="product-image" src="${esc(p.image)}" alt="${esc(p.name)}">`:`<div class="product-monogram">${esc(p.name?.[0]||'A')}<span>${esc(p.category)}</span></div>`}<div class="row"><span class="tiny">${esc(p.sku||'HANDMADE COLLECTION')}</span><span class="badge">${stock(db,p)} in stock</span></div><h3>${esc(p.name)}</h3><div class="product-metrics"><div><small>Price</small><b>${money(p.price)}</b></div><div><small>Profit / unit</small><b>${money(p.price-unitCost(db,p))}</b></div><div><small>Margin</small><b>${p.price?((p.price-unitCost(db,p))/p.price*100).toFixed(0):0}%</b></div></div><p>Stock value ${money(stock(db,p)*unitCost(db,p))} · Potential ${money(stock(db,p)*p.price)}</p><div class="row">${actions(k,p)}${btn('Duplicate','duplicate','text',`data-kind="${k}" data-id="${p.id}"`)}</div></article>`).join('')}</div>`;else if(k==='sales')content=salesTable(rows);else if(k==='notes')content=`<div class="cards">${rows.map(r=>`<article class="panel note"><span class="eyebrow">${esc(r.category)}</span><h3>${esc(r.name)}</h3><p class="prewrap">${esc(r.notes)}</p>${actions(k,r)}</article>`).join('')}</div>`;else if(['packing','booth','tasks'].includes(k))content=`<div class="panel"><div class="row"><h3>${rows.filter(r=>r.completed||r.status==='Done').length} / ${rows.length} complete</h3>${btn('Save as template','save-template','secondary',`data-kind="${k}"`)}</div>${progress(rows.length?rows.filter(r=>r.completed||r.status==='Done').length/rows.length*100:0)}${checklist(k,rows)}<div class="delete-list">${rows.map(r=>`<span>${esc(r.name||r.title)} ${btn('Delete','delete','text danger',`data-kind="${k}" data-id="${r.id}"`)}</span>`).join('')}</div></div>`;else if(k==='goals')content=`<div class="cards">${rows.map(r=>{const cur=goalValue(r),pct=r.target?cur/r.target*100:0;return `<article class="panel"><span class="eyebrow">${esc(r.metric)}</span><h3>${esc(r.name)}</h3><h2>${cur.toFixed(0)} <small>/ ${r.target}</small></h2>${progress(pct)}<p>${pct>=100?'Beautiful work. Goal reached.':pct.toFixed(0)+'% of your goal'}</p>${actions(k,r)}</article>`}).join('')}</div>`;else{const cols=k==='products'?['name','category','price','cost','stock']:k==='events'?['name','date','venue','status']:k==='applications'?['event','deadline','status','paymentStatus']:k==='expenses'?['date','description','category','amount']:k==='customers'?['name','email','interest','followUp']:['name'];content=`<div class="panel table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c.replace(/([A-Z])/g,' $1')}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c==='event'?esc(name('events',r.event)):['price','cost','amount'].includes(c)?money(r[c]):c==='stock'?stock(db,r):esc(r[c]||'—')}${c==='status'&&k==='applications'?progress(applicationProgress(r)):''}</td>`).join('')}<td>${k==='events'?btn('Open','open-event','text',`data-id="${r.id}"`):''}${actions(k,r)}</td></tr>`).join('')}</tbody></table></div>`}return toolbar(k)+(k==='events'?eventFilters():'')+(rows.length?content:empty('No '+k+' yet.',btn('Add your first '+k.replace(/s$/,''),'add','primary',`data-kind="${k}"`)))}
function applicationProgress(r){const checks=[!!r.documentsReady,...(r.jury?[!!r.juryReady]:[]),...(r.insurance?[!!r.insuranceReady]:[]),...(r.permit?[!!r.permitReady]:[]),!!r.submitted,r.paymentStatus==='Paid'];return Math.round(checks.filter(Boolean).length/checks.length*100)}
function goalValue(r){const m=metrics(db,r.metric==='Event Revenue'?r.event:'',r.month?r.month+'-01':'',r.month?r.month+'-31':'9999');return {'Monthly Revenue':m.revenue,'Monthly Profit':m.net,'Event Revenue':m.revenue,'Number of Events':db.events.filter(e=>!r.month||e.date?.startsWith(r.month)).length,'Units Sold':m.units,'Average Order Value':m.aov}[r.metric]||0}
function inventory(){return `<div class="toolbar"><input id="search" aria-label="Search inventory" placeholder="Search products…" value="${esc(query)}"></div><div class="notice">Plan how many units to take, even before you make them. Market Tools shows the shortages after reservations. Sales, returns and stock adjustments retain their history.</div>${btn('+ Allocate to event','add','primary','data-kind="allocations"')}<div class="panel table-wrap space"><table><thead><tr><th>Product</th><th>In stock</th><th>Reserved</th><th>Minimum</th><th>Stock value</th><th></th></tr></thead><tbody>${db.products.filter(p=>!query||JSON.stringify(p).toLowerCase().includes(query.toLowerCase())).map(p=>`<tr><td><b>${esc(p.name)}</b>${stock(db,p)<=p.minStock?'<span class="badge warning">Low stock</span>':''}</td><td>${stock(db,p)}</td><td>${p.reserved||0}</td><td>${p.minStock||0}</td><td>${money(stock(db,p)*unitCost(db,p))}</td><td>${btn('Update stock','edit','text',`data-kind="products" data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table>${!db.products.length?empty('Make room for your first collection.',btn('Add product','add','primary','data-kind="products"')):''}</div><h2>Event stock plans</h2><div class="cards">${db.allocations.filter(a=>!eventId||a.event===eventId).map(a=>`<article class="panel"><span class="eyebrow">${esc(name('events',a.event))}</span><h3>${esc(name('products',a.product))}</h3><div class="product-metrics"><div><small>Taking</small><b>${a.quantity}</b></div><div><small>Sold</small><b>${sold(db,a.product,a.event)}</b></div><div><small>At booth</small><b>${a.quantity-sold(db,a.product,a.event)}</b></div></div>${actions('allocations',a)}</article>`).join('')}</div>`}
function commandCenter(){const e=db.events.find(e=>e.id===eventId);if(!e){eventId='';return listing('events')}const m=metrics(db,e.id),days=Math.round((new Date(e.date+'T00:00')-new Date(today()+'T00:00'))/86400000);let content='';const map={Inventory:'inventory',Sales:'sales',Expenses:'expenses',Booth:'booth',Packing:'packing',Tasks:'tasks',Customers:'customers',Notes:'notes'};if(tab==='Overview')content=`${kpis([['Days until event',Math.max(0,days),esc(e.date)],['Revenue',money(m.revenue),'Goal '+money(e.salesGoal)],['Net profit',money(m.net),'COGS '+money(m.cogs)],['ROI',m.roi===null?'—':m.roi.toFixed(1)+'%','Expenses '+money(m.expenses)]])}<div class="two-col"><article class="panel"><h3>Ready for market day</h3>${['Application','Payment','Inventory','Booth','Packing','Marketing','Travel','Permits'].map(t=>{const val=t==='Packing'?done('packing',e.id):t==='Booth'?done('booth',e.id):t==='Inventory'?inventoryReady(e.id):e.prep?.[t]?100:0;return `<div class="prep-row"><span>${t}</span>${['Packing','Booth','Inventory'].includes(t)?`<b>${val}%</b>`:`<input type="checkbox" aria-label="${t} complete" data-prep="${t}" ${val?'checked':''}>`}${progress(val)}</div>`}).join('')}</article><article class="panel"><span class="eyebrow">THE DETAILS</span><h3>${esc(e.venue||'Your market')}</h3><p>${esc(e.address)} ${esc(e.city)} ${esc(e.region)}</p><p>${esc(e.start||'')} – ${esc(e.end||'')} · Booth ${esc(e.boothNumber||'—')}</p><p class="prewrap">${esc(e.notes||'Add organizer details, arrival instructions, and your plans for the day.')}</p>${btn('Edit event details','edit','secondary',`data-kind="events" data-id="${e.id}"`)}</article></div>`;else if(tab==='Market Tools')content=marketTools(e.id);else if(tab==='Post-Event Review')content=`<form id="reviewForm" class="panel"><h2>A moment to reflect.</h2><div class="form-grid">${[F('traffic','How was foot traffic?'),F('location','How was the booth location?'),F('best','What sold best?'),F('poor','What sold poorly?'),F('requests','What did customers ask for?'),F('restock','What should be restocked?'),F('change','What should change next time?'),F('rating','Overall rating','select','1|2|3|4|5'),F('again','Would attend again','checkbox'),F('notes','Overall notes','textarea')].map(f=>input(f,e.review||{})).join('')}</div><button class="primary">Save review</button></form>`;else if(tab==='Booth')content=`<form id="boothForm" class="panel"><h3>Your booth setup</h3><div class="form-grid">${[F('width','Width'),F('depth','Depth'),F('setting','Setting','select','Indoor|Outdoor'),...['Tent','Tables','Shelving','Grid Walls','Checkout Area','Storage','Lighting','Power','Signage','Decor','Weather Protection'].map(t=>F(t,t))].map(f=>input(f,e.boothSetup||{})).join('')}</div><button class="primary">Save booth setup</button></form>${listing('booth')}`;else content=map[tab]==='inventory'?inventory():listing(map[tab]);return `<div class="heading"><div><button class="text" data-action="back-events">← All events</button><h1>${esc(e.name)}</h1><p>${esc(e.date)} · ${esc(e.venue)} · Booth ${esc(e.boothNumber||'—')}</p></div>${btn('+ Quick sale','add','primary','data-kind="sales"')}</div><div class="tabs">${['Overview','Market Tools',...Object.keys(map),'Post-Event Review'].map(t=>btn(t,'event-tab',tab===t?'active':'text',`data-tab="${t}"`)).join('')}</div>${content}`}
function deadlines(){return [...db.events.flatMap(e=>[{date:e.date,label:e.name,kind:'events',id:e.id},{date:e.deadline,label:'Apply: '+e.name,kind:'events',id:e.id},...(e.paymentStatus!=='Paid'?[{date:e.paymentDue,label:'Payment: '+e.name,kind:'events',id:e.id}]:[])]),...db.applications.flatMap(a=>[{date:a.deadline,label:'Application: '+name('events',a.event),kind:'applications',id:a.id},{date:a.followUp,label:'Application follow-up',kind:'applications',id:a.id}]),...db.tasks.filter(t=>t.status!=='Done').map(t=>({date:t.due,label:t.title,kind:'tasks',id:t.id})),...db.customers.map(c=>({date:c.followUp,label:'Follow up: '+c.name,kind:'customers',id:c.id}))].filter(x=>x.date)}
function calendar(){const y=cal.getFullYear(),m=cal.getMonth(),first=new Date(y,m,1).getDay(),count=new Date(y,m+1,0).getDate(),all=deadlines();return `<div class="row calendar-controls"><label>Jump to month<input type="month" id="calendarJump" value="${y}-${String(m+1).padStart(2,'0')}"></label>${btn('Today','cal-today')}${btn('←','cal-prev','secondary','aria-label="Previous month"')}<h2>${cal.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2>${btn('→','cal-next','secondary','aria-label="Next month"')}</div><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array(first).fill('<div class="day muted"></div>').join('')}${Array.from({length:count},(_,i)=>{const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day ${d===today()?'today':''}"><b>${i+1}</b>${all.filter(x=>x.date===d).map(x=>`<button class="calendar-item ${x.kind}" data-action="related" data-kind="${x.kind}" data-id="${x.id}">${esc(x.label)}</button>`).join('')}</div>`}).join('')}</div>`}
function range(){const d=new Date(),y=d.getFullYear(),m=d.getMonth(),ym=(year,month)=>`${year}-${String(month+1).padStart(2,'0')}`,monthRange=(year,month)=>[ym(year,month)+'-01',ym(year,month)+'-'+new Date(year,month+1,0).getDate()];if(period==='This Month')return monthRange(y,m);if(period==='Last Month'){const last=new Date(y,m-1,1);return monthRange(last.getFullYear(),last.getMonth())}if(period==='This Year')return[y+'-01-01',y+'-12-31'];return[from||'',to||'9999']}

function analytics(reports=false){const [f,t]=range();return `<div class="toolbar analytics-filters"><label>Period<select id="period" aria-label="Reporting period">${['This Month','Last Month','This Year','Custom Range'].map(x=>`<option ${x===period?'selected':''}>${x}</option>`).join('')}</select></label>${period==='Custom Range'?`<label>From<input id="from" type="date" value="${from}"></label><label>To<input id="to" type="date" value="${to}"></label>`:''}<label>Market<select id="insightEvent"><option value="">All markets + unassigned</option>${db.events.map(e=>`<option value="${esc(e.id)}" ${e.id===db.settings.insightEvent?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>${btn('Open Print Center','print','secondary')}</div><p class="chart-note">${esc(f||'First record')} — ${esc(t==='9999'?'Latest record':t)} · ${db.demo?'Sample workspace':'Your saved records'} · Updates when you save a record.</p>${f>t?'<p class="notice" role="alert">Choose an end date on or after the start date.</p>':renderInsights(db,f,t,money,{event:db.events.some(e=>e.id===db.settings.insightEvent)?db.settings.insightEvent:''})}${inventoryInsights(db,money)}`}

const starters=[['First Craft Fair Checklist','tasks','Research a market\nSubmit application\nPlan stock\nTest checkout\nExport a backup'],['Outdoor Market Checklist','booth','Tent\nTent weights\nWeather protection\nWaterproof storage'],['Indoor Market Checklist','booth','Confirm access time\nMeasure table space\nCheck power access'],['Booth Setup Checklist','booth','Tables\nTablecloth\nDisplay risers\nPrice signs\nCheckout area'],['Application Checklist','tasks','Read vendor rules\nGather jury photos\nCheck insurance\nSubmit application'],['Packing Checklist','packing','Products\nCard reader\nCash float\nBags\nTape\nWater'],['Market Day Checklist','tasks','Count opening stock\nTest card reader\nPhotograph booth\nRecord every sale'],['Closing Checklist','tasks','Count remaining inventory\nPack displays\nReconcile payments\nClean booth space'],['Post-Event Review','tasks','Review sales\nIdentify bestsellers\nRecord customer requests\nRate event\nPlan restock']];
function templates(){return `<p class="intro">A thoughtful starting point. Copy a checklist into your event, then make it your own.</p>${btn('+ New template','add','primary','data-kind="templates"')}<div class="cards space">${[...starters.map((x,i)=>({id:'starter'+i,name:x[0],type:x[1],items:x[2]})),...db.templates].map(r=>`<article class="panel"><span class="eyebrow">${esc(r.type)} · ${r.items.split('\n').length} ITEMS</span><h3>${esc(r.name)}</h3><p class="prewrap">${esc(r.items)}</p>${btn('Use template','use-template','secondary',`data-id="${r.id}"`)}${!r.id.startsWith('starter')?actions('templates',r):btn('Customize copy','copy-template','text',`data-id="${r.id}"`)}</article>`).join('')}</div>`}
const themes={'Olive Atelier':['#4b5744','#f4f3e8','#b49a64'],'Market Linen':['#766952','#f8f3e9','#bfa57e'],'Forest Artisan':['#27584e','#edf5ee','#b28d61'],'Terracotta Maker':['#a4553e','#faf0e7','#86916a'],'Warm Sage':['#718676','#eff5ec','#bb956f'],'Antique Gold':['#866a36','#f8f2df','#9a715d'],'Rosewood Studio':['#884f66','#faf0f3','#bc936b'],'Coastal Blue':['#365f7c','#edf4fa','#bd9c69'],'Lavender Paper':['#706185','#f3eff9','#ac9271']};function legacyTheme(){if(demoImages(db))save();if(db.settings.designRevision!==3){Object.assign(db.settings,{designRevision:3,theme:'Olive Atelier',typography:'Editorial',radius:4,cardStyle:'Flat'});delete db.settings.accent;delete db.settings.background;save()}const t=themes[db.settings.theme]||themes['Market Linen'];document.documentElement.style.setProperty('--accent',db.settings.accent||t[0]);document.documentElement.style.setProperty('--bg',db.settings.background||t[1]);document.documentElement.style.setProperty('--gold',t[2]);document.documentElement.style.setProperty('--radius',(db.settings.radius||12)+'px');document.body.classList.toggle('modern',db.settings.typography==='Modern');document.body.classList.toggle('flat',db.settings.cardStyle==='Flat')}
function legacyThemeStudio(){return `<p class="intro">A workspace that feels like your studio.</p><div class="cards">${Object.entries(themes).map(([n,c])=>`<button class="panel theme" data-action="theme" data-theme="${n}"><div class="swatches">${c.map(v=>`<i style="background:${v}"></i>`).join('')}</div><h3>${n}</h3><p>${db.settings.theme===n?'Your current theme':'Apply this palette'}</p></button>`).join('')}</div><form id="themeForm" class="panel space"><h3>The finishing touches</h3><div class="form-grid">${input(F('typography','Typography pairing','select','Editorial|Modern'),db.settings)}${input(F('cardStyle','Card style','select','Soft|Flat'),db.settings)}${input(F('radius','Corner radius','select','4|8|12|20'),db.settings)}</div><button class="primary">Save appearance</button></form>`}
function backup(){if(publicDemo)return `<div class="panel"><h2>Try it with sample data.</h2><p>This public demo resets when you reload. Use example details only. The full app saves your business locally and includes portable JSON backups.</p>${btn('Reset sample workspace','remove-demo','secondary')}<p><a href="https://billionar.github.io/aurelystudio-craft-vendor__" target="_blank" rel="noopener">Open the full app ↗</a></p></div>`;return `<div class="panel"><span class="eyebrow">YOURS TO KEEP</span><h2>Your business. Your data.</h2><p>Your planner data stays in this browser unless you export it. No account is required.</p><p>Export regularly, especially before changing devices or clearing browser storage. Import replaces the current workspace after confirmation.</p><div class="quick-actions">${btn('Export backup','export','primary')}<label class="button secondary">Import backup<input id="import" type="file" accept="application/json" hidden></label></div></div><div class="two-col space"><article class="panel"><h3>Explore the possibilities</h3><p>Demo uses a separate sample workspace. Your real business data is kept aside and restored when you leave demo.</p>${btn(db.demo?'Reset demo data':'Load demo business','demo','secondary')}${db.demo?btn('Remove demo data','remove-demo','secondary'):''}</article><article class="panel"><h3>A fresh start</h3><p>Clears the current workspace. Export a backup first.</p>${btn('Clear all data','clear','secondary danger')}</article></div>`}
function help(){return `<div class="panel help"><span class="eyebrow">A LITTLE GUIDANCE</span><h2>From first market to your next chapter.</h2>${[['Getting started','Set up your business, add products, and create an event. Every saved record stays in this browser.'],['Adding events','Add dates, application deadlines, fees and a sales goal. Open an event to manage its entire preparation and review.'],['Preparing inventory','Current stock includes opening stock, production, adjustments, sales and sellable returns. Variants have separate stock. Set sales consume their components. Plans may exceed available stock; Market Tools calculates what to make after other upcoming plans and held stock. Record made quantities only after production is complete.'],['Recording sales','Tap Quick Sale, select products, adjust quantities and record payment. Discounts are a fixed transaction amount. Cost, product name and category are stored at the time of sale, so later product changes do not rewrite historical profit. Editing an unrefunded sale adjusts inventory. Use Return to reverse a sale; refunded sales are locked and remain in history.'],['Tracking expenses','Fees entered on the event are automatically included on the event date. Do not enter those fees again in Expenses. Application tracker fees are reference-only. Use Expenses for additional costs.'],['Understanding profit','Revenue = sales after discounts minus refunds. COGS uses recorded unit costs, reduced only for sellable returned items. Gross profit = revenue − COGS. Net profit = revenue − COGS − event fees − additional expenses. Material purchases entered as expenses are counted in addition to unit costs; avoid counting the same materials twice. This is a planning summary, not tax accounting.'],['Understanding ROI','ROI = net profit ÷ event expenses × 100. Event expenses include event setup fees and additional linked expenses. If expenses are zero, ROI is shown as unavailable. Date filters use the sale date, expense date and event date respectively.'],['Calendar & preparation','Calendar combines markets, application deadlines, unpaid payment dates, tasks and customer follow-ups. Packing and booth checklists update event progress. Application, Payment, Marketing, Travel and Permits in event preparation are manual readiness checks.'],['Backup & restore','Export JSON from Backup & Data. Import a valid exported backup to replace the workspace. Browser storage does not sync across devices. Keep backups somewhere safe.'],['Data privacy & offline use','No separate app account is required. Data stays in this browser. Hosting access may require sign-in. Optional remote image URLs contact their image hosts. Core pages can work offline after the app has loaded on a supported HTTPS host. Private hosting access may still require an online connection to open initially.'],['Demo business','Demo records are clearly marked. Your real workspace is kept separately. Leave demo to restore it.']].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}${btn('Reopen setup','setup','primary')}</div>`}
function setup(){let step=0,draft={};const steps=[[F('businessName','Business name'),F('owner','Owner name'),F('businessType','Business type'),F('category','Main product category'),F('currency','Currency','select','USD|EUR|GBP|TRY|CAD|AUD|NZD')],[F('eventName','Event name'),F('eventDate','Date','date'),F('venue','Location'),F('boothFee','Booth fee','number'),F('salesGoal','Sales goal','number')],[F('productName','Product name'),F('productCategory','Category'),F('price','Price','number'),F('cost','Cost','number'),F('stock','Current stock','number')],[F('monthlyGoal','Monthly revenue goal','number'),F('eventGoal','Next event sales goal','number')]];function show(){if($('#modal').open)$('#modal').close();modal(`<form id="setupForm"><p class="eyebrow">WELCOME TO CRAFT FAIR VENDOR OS · ${step+1} / 4</p><h2>${['Your business','Your first event','Your first product','Your goal'][step]}</h2>${progress((step+1)*25)}<div class="form-grid space">${steps[step].map(f=>input(f,{...db.settings,...draft})).join('')}</div><footer>${btn('Skip setup','skip-setup','text','type="button"')}${step?'<button type="button" id="setupBack" class="secondary">Back</button>':''}<button class="primary">${step===3?'Finish setup':'Continue'}</button></footer></form>`);const capture=()=>{const f=new FormData($('#setupForm'));steps[step].forEach(x=>draft[x.key]=x.type==='number'?Number(f.get(x.key)||0):f.get(x.key))};$('#setupBack')?.addEventListener('click',()=>{capture();step--;show()});$('#setupForm').onsubmit=e=>{e.preventDefault();capture();if(step<3){step++;show();return}Object.assign(db.settings,{businessName:draft.businessName||db.settings.businessName,owner:draft.owner,currency:draft.currency||'USD',businessType:draft.businessType,category:draft.category,onboarded:true});let id='';if(draft.eventName){id=uid();db.events.push({id,name:draft.eventName,date:draft.eventDate||today(),venue:draft.venue,boothFee:draft.boothFee||0,salesGoal:draft.salesGoal||0,status:'Planning'})}if(draft.productName)db.products.push({id:uid(),name:draft.productName,category:draft.productCategory,price:draft.price||0,cost:draft.cost||0,stock:Math.floor(draft.stock||0),minStock:0,reserved:0});if(draft.monthlyGoal)db.goals.push({id:uid(),name:'Monthly revenue',metric:'Monthly Revenue',target:draft.monthlyGoal,month:today().slice(0,7)});if(draft.eventGoal&&id)db.goals.push({id:uid(),name:'Next event sales',metric:'Event Revenue',target:draft.eventGoal,event:id});save();$('#modal').close();go('dashboard')}}show()}
function render(){const menuScroll=document.querySelector('.sidebar>nav')?.scrollTop||0;applyTheme();let idx=0;const nav=Object.entries(groups).map(([group,items])=>`<section><h4>${group}</h4>${items.map(label=>{const p=keyOf(label);return `<button data-action="nav" data-page="${p}" class="nav-item ${page===p?'selected':''}" title="${label}"><span>${icon(label)}</span><b>${label}</b></button>`}).join('')}</section>`).join('');let content;if(eventId)content=commandCenter();else if(page==='dashboard')content=dashboard();else if(page==='inventory')content=inventory();else if(page==='calendar')content=calendar();else if(page==='analytics'||page==='reports')content=analytics(page==='reports');else if(page==='templates')content=templates();else if(extraPages().includes(page))content=operations(page);else if(page==='theme-studio')content=themeStudio();else if(page==='backup-data')content=backup();else if(page==='help')content=help();else content=listing(page==='booth-planner'?'booth':(schemas[page]||page==='sales')?page:'notes');$('#app').innerHTML=`<div class="shell ${collapsed?'collapsed':''}"><aside class="sidebar"><button class="brand" data-action="nav" data-page="dashboard">AurelyStudio<small>CRAFT FAIR VENDOR OS</small></button><button class="studio business-name" data-action="business-name" aria-label="Edit business name" title="Edit business name"><span class="business-label">YOUR BUSINESS</span><span class="business-value">${esc(db.settings.businessName==='Your maker business'?'Add your business name':db.settings.businessName||'Add your business name')}</span><small>Edit name <span aria-hidden="true">↗</span></small></button><nav>${nav}</nav><div class="sidebar-bottom"><p>Make more<br><em>good things happen.</em></p>${btn('⇤','collapse','text','aria-label="Collapse sidebar"')}</div></aside><main><header class="app-top"><button class="icon mobile-menu" data-action="mobile-menu" aria-label="Open navigation">☰</button><span>Your studio <span class="crumb">/ ${eventId?'Event workspace':titleOf(page)}</span></span><div>${page==='dashboard'?`<input class="dashboard-month" type="month" aria-label="Dashboard month" id="dashboardMonth" value="${dashboardMonth}">`:`<span class="saved">${publicDemo?'Sample changes · reset on reload':'Saved on this device'}</span>`}<button class="avatar" data-action="setup" aria-label="Business settings">${esc(db.settings.businessName?.[0]||'A')}</button></div></header>${db.demo?`<div class="demo-banner"><span>${publicDemo?'INTERACTIVE DEMO · Sample data · Changes reset on reload':'SAMPLE WORKSPACE · The Sunday Studio'}</span>${btn(publicDemo?'Reset demo':'Leave demo','remove-demo','text')}</div>`:''}<div class="workspace">${!eventId&&page!=='dashboard'?`<div class="heading"><div><p class="eyebrow">CRAFT FAIR VENDOR OS</p><h1>${titleOf(page)}</h1></div></div>`:''}${content}<footer class="workspace-footer">A little structure. More room to create.<span>AURELYSTUDIO</span></footer></div></main><nav class="bottom-nav">${[['Home','dashboard'],['Events','events'],['+ Sale','sale'],['Inventory','inventory'],['More','more']].map(([n,p])=>btn(n,p==='sale'?'add':p==='more'?'mobile-menu':'nav',p==='sale'?'quick':'text',`data-page="${p}" data-kind="sales"`)).join('')}</nav></div>`;bindForms();bindExtra();brandAll();const menu=document.querySelector('.sidebar>nav');if(menu)menu.scrollTop=menuScroll;}
function bindForms(){$('#dashboardMonth')?.addEventListener('change',e=>{if(e.target.value){dashboardMonth=e.target.value;render()}});for(const key of ['eventMonth','eventYear','eventLocation','eventType'])$('#'+key)?.addEventListener('change',e=>{if(key==='eventMonth')eventMonth=e.target.value;if(key==='eventYear')eventYear=e.target.value;if(key==='eventLocation')eventLocation=e.target.value;if(key==='eventType')eventType=e.target.value;render()});for(const [id,key] of [['search','query'],['filter','filter'],['sort','sort']])$('#'+id)?.addEventListener(id==='search'?'input':'change',e=>{const pos=e.target.selectionStart;if(key==='query')query=e.target.value;if(key==='filter')filter=e.target.value;if(key==='sort')sort=e.target.value;render();if(id==='search'){$('#search').focus();$('#search').setSelectionRange(pos,pos)}});$('#period')?.addEventListener('change',e=>{period=e.target.value;render()});for(const k of ['from','to'])$('#'+k)?.addEventListener('change',e=>{if(k==='from')from=e.target.value;else to=e.target.value;render()});$('#reviewForm')?.addEventListener('input',e=>{const f=new FormData(e.currentTarget);db.events.find(x=>x.id===eventId).review={...Object.fromEntries(f),again:f.has('again')};save()});$('#boothForm')?.addEventListener('input',e=>{db.events.find(x=>x.id===eventId).boothSetup=Object.fromEntries(new FormData(e.currentTarget));save()});$('#reviewForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);db.events.find(x=>x.id===eventId).review={...Object.fromEntries(f),again:f.has('again')};save();toast('Review saved')});$('#boothForm')?.addEventListener('submit',e=>{e.preventDefault();db.events.find(x=>x.id===eventId).boothSetup=Object.fromEntries(new FormData(e.target));save();toast('Booth setup saved')});$('#themeForm')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(db.settings,Object.fromEntries(new FormData(e.target)));save();render();toast('Appearance saved')});$('#import')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const v=auditV2(verifyIntegrity(JSON.parse(await file.text())));if(await ask('Replace the current workspace with this backup? Export your current data first.')){clearDrafts();const wasDemo=db.demo;db=v;db.demo=!!wasDemo;save();go('dashboard');toast('Backup restored')}}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}})}
async function startDemo(){if(db.demo){if(!await ask('Reset all sample workspace changes?'))return}else{try{localStorage.setItem(KEY+'-real',JSON.stringify(db))}catch{return toast('Unable to preserve your workspace. Export a backup first.')}}db=demo();save();go('dashboard')}
function clearDrafts(){for(const k of Object.keys(localStorage))if(k.startsWith(KEY+'-draft-'))localStorage.removeItem(k)}
async function leaveDemo(){if(publicDemo){db=demo();go('dashboard');return}if(!await ask('Remove the sample workspace and restore your real business?'))return;try{db=migrate(JSON.parse(localStorage.getItem(KEY+'-real'))||blank())}catch{db=blank()}save();localStorage.removeItem(KEY+'-real');go('dashboard')}
function getTemplate(id){if(id.startsWith('starter')){const x=starters[Number(id.slice(7))];return {name:x[0],type:x[1],items:x[2]}}return db.templates.find(x=>x.id===id)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,k=b.dataset.kind,id=b.dataset.id;if(a==='nav')go(b.dataset.page);if(a==='chart-week'){period='Custom Range';from=b.dataset.from;to=b.dataset.to;go('analytics')}if(a==='close')$('#modal').close();if(a==='add')editor(k);if(a==='edit')editor(k,id);if(a==='delete')remove(k,id);if(a==='collapse'){collapsed=!collapsed;render()}if(a==='mobile-menu')$('.sidebar').classList.toggle('mobile-open');if(a==='view'){view=view==='cards'?'table':'cards';render()}if(a==='open-event'||a==='related'&&k==='events'){page='events';eventId=id;tab='Overview';query='';filter='';render()}else if(a==='related')editor(k,id);if(a==='event-tab'){tab=b.dataset.tab;query='';filter='';render()}if(a==='back-events')go('events');if(a==='cal-today'){cal=new Date();render()}if(a==='cal-prev'||a==='cal-next'){cal=new Date(cal.getFullYear(),cal.getMonth()+(a==='cal-next'?1:-1),1);render()}if(a==='duplicate'){const r=structuredClone(db[k].find(r=>r.id===id));r.id=uid();r.name+=' (copy)';if(k==='products')r.stock=0;db[k].push(r);save();render();toast('Copy created with zero starting stock')}if(a==='theme'){delete db.settings.main;db.settings.theme=b.dataset.theme;delete db.settings.accent;delete db.settings.background;save();render()}if(a==='demo')startDemo();if(a==='remove-demo')leaveDemo();if(a==='clear'&&await ask('Permanently clear all data in this workspace?')){clearDrafts();const isDemo=db.demo;db=blank();db.demo=isDemo;save();render();toast('Workspace cleared')}if(a==='export'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='AurelyStudio-Vendor-Backup-'+today()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup download requested')}if(a==='print')go('print-studio');if(a==='business-name')businessNameEditor();if(a==='setup')setup();if(a==='start'){go('dashboard');if(!db.settings.onboarded)setup()}if(a==='enter')go('dashboard');if(a==='skip-setup'){db.settings.onboarded=true;save();$('#modal').close();go('dashboard')}if(a==='welcome-info'){const info=b.dataset.info;go(info==='Templates'?'templates':'help')}if(a==='copy-template'){const r=getTemplate(id);db.templates.push({...r,id:uid(),name:r.name+' (copy)'});save();render()}if(a==='use-template'){const r=getTemplate(id);modal(`<form id="templateForm"><h2>${esc(r.name)}</h2><p>Choose the event for this editable checklist.</p>${input(eventField)}<footer>${btn('Cancel','close','secondary','type="button"')}<button class="primary">Add checklist</button></footer></form>`);$('#templateForm').onsubmit=e=>{e.preventDefault();const ev=new FormData(e.target).get('event');r.items.split('\n').filter(x=>x.trim()).forEach(item=>db[r.type].push({id:uid(),event:ev,[r.type==='tasks'?'title':'name']:item,category:'Preparation',quantity:1,completed:false,status:'To Do',priority:'Medium'}));save();$('#modal').close();go(r.type==='booth'?'booth-planner':r.type);toast('Checklist added — ready to customize')}}if(a==='save-template'){const items=filtered(k).map(r=>r.name||r.title);if(!items.length)return toast('Add checklist items first.');const n=await ask('Name your reusable template',true);if(n){db.templates.push({id:uid(),name:n,type:k,items:items.join('\n')});save();toast('Template saved')}}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check){const r=db[t.dataset.check].find(x=>x.id===t.dataset.id);if(t.dataset.check==='tasks')r.status=t.checked?'Done':'To Do';else r.completed=t.checked;save();render()}if(t.dataset.prep){const ev=db.events.find(x=>x.id===eventId);ev.prep={...ev.prep,[t.dataset.prep]:t.checked};save();render()}});
window.addEventListener('hashchange',()=>{const next=entryRoute();if(next!==page){page=next;eventId='';query='';filter='';render()}});window.addEventListener('storage',e=>{if(!publicDemo&&e.key===KEY&&e.newValue){try{db=auditV2(verifyIntegrity(JSON.parse(e.newValue)));render();toast('Workspace updated in another tab')}catch{}}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});render();if(!db.settings.calm)playIntro();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function eventFilters(){const pick=(id,label,values,current)=>`<select id="${id}" aria-label="${label}"><option value="">${label}</option>${values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select>`;return `<div class="toolbar">${pick('eventMonth','All months',Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0')),eventMonth)}${pick('eventYear','All years',[...new Set(db.events.map(e=>e.date?.slice(0,4)).filter(Boolean))].sort(),eventYear)}${pick('eventLocation','All locations',[...new Set(db.events.map(e=>e.city||e.venue).filter(Boolean))],eventLocation)}${pick('eventType','All event types',[...new Set(db.events.map(e=>e.type).filter(Boolean))],eventType)}${btn('Calendar view','nav','secondary','data-page="calendar"')}</div>`}

async function ask(message,needText=false){return new Promise(resolve=>{modal(`<form id="confirmForm"><p class="eyebrow">YOUR WORKSPACE</p><h2>${needText?'Name your template':'Please confirm'}</h2><p>${esc(message)}</p>${needText?'<label>Template name<input name="answer" required></label>':''}<footer><button type="button" id="confirmCancel" class="secondary">Cancel</button><button class="primary" type="submit">${needText?'Save template':'Confirm'}</button></footer></form>`);let complete=false;const finish=v=>{if(complete)return;complete=true;$('#modal').close();resolve(v)};$('#confirmForm').onsubmit=e=>{e.preventDefault();finish(needText?new FormData(e.target).get('answer'):true)};$('#confirmCancel').onclick=()=>finish(false);$('#modal').addEventListener('close',()=>finish(false),{once:true})})}

function extraPages(){return ['market-tools','stock-history','custom-orders','print-studio']}
function productEditor(id){
 const old=db.products.find(p=>p.id===id),r={kind:'Individual',price:0,cost:0,stock:0,reserved:0,...old};r.stock=old?stock(db,old):0;
 const fields=[F('name','Product name'),F('kind','Product type','select','Individual|Variant|Set'),F('family','Product family'),F('variant','Variant: scent, color or size'),F('sku','SKU'),F('category','Category'),F('price','Selling price','number'),F('cost','Unit cost (individual / variant)','number'),F('stock','Counted stock (individual / variant)','number'),F('reserved','Held aside for orders','number'),F('minStock','Low-stock threshold','number'),F('image','Product image URL','url'),F('care','Care instructions','textarea'),F('notes','Notes','textarea')];
 modal(`<form id="productForm"><div class="modal-head"><h2>${id?'Edit product':'New product'}</h2>${btn('×','close','icon','type="button" aria-label="Close"')}</div><p>Give each variant its own name and SKU. Set availability and cost come from its components.</p><div class="form-grid">${fields.map(f=>input(f,r)).join('')}</div><details ${r.kind==='Set'?'open':''}><summary>Set contents</summary><p>Enter the number of each individual item in one set. Use zero to leave an item out.</p><div class="form-grid">${db.products.filter(p=>p.id!==id&&p.kind!=='Set').map(p=>`<label>${esc(p.name)}<input type="number" min="0" step="1" data-component="${p.id}" value="${r.components?.find(c=>c.product===p.id)?.qty||0}"></label>`).join('')||'<p>Add individual products first.</p>'}</div></details><p class="form-error" role="alert"></p><footer><button class="primary">Save product</button></footer></form>`);
 $('#productForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),p={...old,id:id||uid()};for(const field of fields)p[field.key]=field.type==='number'?Number(f.get(field.key)||0):f.get(field.key);p.components=p.kind==='Set'?[...e.target.querySelectorAll('[data-component]')].filter(x=>Number(x.value)>0).map(x=>({product:x.dataset.component,qty:Number(x.value)})):[];
 if(old&&old.kind!==p.kind&&(old.kind==='Set'||p.kind==='Set')&&(db.sales.some(s=>s.lines.some(l=>l.product===id))||db.allocations.some(a=>a.product===id)||db.movements.some(m=>m.product===id)||db.products.some(x=>x.components?.some(c=>c.product===id))))throw Error('This product has linked history. Create a new product to change between an item and a set.');
 validateProduct(db,p);const counted=p.stock;if(old)p.stock=old.stock;
 if(p.kind==='Set'){p.stock=0;p.cost=unitCost(db,p)}
 if(old&&p.kind!=='Set'){const delta=counted-physical(db,old);if(delta)db.movements.push({id:uid(),product:id,delta,date:today(),reason:'Count correction',createdAt:new Date().toISOString()})}
 if(old)db.products=db.products.map(x=>x.id===id?p:x);else db.products.push(p);save();$('#modal').close();render();toast('Product saved. Stock history updated.')}catch(err){$('.form-error').textContent=err.message}};
}
function operations(p){if(p==='market-tools')return marketTools();if(p==='stock-history')return stockHistory();if(p==='custom-orders')return ordersView();if(p==='print-studio')return printStudio()}
function selectedEvent(id){return db.events.find(e=>e.id===(id||db.settings.toolsEvent))||db.events.filter(e=>!['Completed','Cancelled'].includes(e.status)).sort((a,b)=>a.date.localeCompare(b.date))[0]||db.events[0]}
function marketTools(id){const e=selectedEvent(id);if(!e)return empty('Plan your first market to begin.',btn('Add event','add','primary','data-kind="events"'));const plan=production(db,e.id),logs=db.timeLogs.filter(t=>t.event===e.id),hours=logs.reduce((a,t)=>a+t.hours,0),m=metrics(db,e.id),plans=db.allocations.filter(a=>a.event===e.id),qty=plans.reduce((a,x)=>a+x.quantity,0),mix=key=>qty?plans.reduce((a,x)=>{const p=db.products.find(p=>p.id===x.product);return a+x.quantity*(key==='price'?p.price:unitCost(db,p))},0)/qty:0;
 const be={price:round(mix('price')),cost:round(mix('cost')),feePercent:0,feeFixed:0,...e.breakEven};const cl={date:e.date||today(),opening:0,paidOut:0,counted:0};
 return `<div class="toolbar"><label>Market<select id="toolsEvent">${db.events.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.name)} · ${esc(x.date)}</option>`).join('')}</select></label>${btn('Edit event costs','edit','secondary',`data-kind="events" data-id="${e.id}"`)}</div><div class="two-col tools-top"><form id="breakForm" class="panel" data-event="${e.id}"><span class="eyebrow">01 / BEFORE YOU BOOK</span><h2>Will this market pay off?</h2><p>Start with your planned sales mix, or adjust your estimate. Include materials, packaging and any paid labor in unit cost.</p><div class="form-grid">${[F('price','Average selling price','number'),F('cost','Average unit cost','number'),F('feePercent','Payment fee %','number'),F('feeFixed','Payment fee per item','number')].map(f=>input(f,be)).join('')}</div><div id="breakResult" class="result-strip">${breakResult(e,be)}</div><small>Estimate only. Fixed costs include event fees and additional linked expenses. The result rounds up to whole units.</small></form><article class="panel"><span class="eyebrow">02 / AT THE MAKING TABLE</span><h2>Your production list</h2><p>Available stock excludes held stock and other upcoming market plans. Sets expand into individual components.</p>${btn('Add planned quantity','add','secondary',`data-kind="allocations"`)}<div class="production-list">${plan.map(r=>`<div><span><b>${esc(r.product.name)}</b><small>Need ${r.required} · Available ${r.available} · Other plans ${r.other}</small></span><strong>${r.missing?'Make '+r.missing:'Ready'}</strong>${r.missing?btn('Record made','produce','text',`data-id="${r.product.id}" data-qty="${r.missing}"`):''}</div>`).join('')||'<p>Add an event stock plan to calculate what to make.</p>'}</div></article></div><div class="two-col space"><form id="cashForm" class="panel" data-event="${e.id}"><span class="eyebrow">03 / CLOSE YOUR MARKET DAY</span><h2>Every note accounted for.</h2><div class="form-grid">${[F('date','Market day','date'),F('opening','Opening cash','number'),F('paidOut','Cash paid out','number'),F('counted','Counted closing cash','number'),F('notes','Closing notes','textarea')].map(f=>input(f,cl)).join('')}</div><div id="cashResult" class="result-strip">${cashResult(e.id,cl)}</div><p class="tiny">Cash paid out adjusts the drawer only. Add its business cost to Expenses separately, if it is not already recorded. Custom-order deposits are excluded; use a separate drawer for them.</p><p class="form-error" role="alert"></p><button class="primary">Save closing snapshot</button></form><article class="panel"><span class="eyebrow">04 / YOUR TIME HAS VALUE</span><h2>Was it worth your time?</h2>${kpis([['Total time',hours.toFixed(2)+' h'],['Net profit / hour',hours?money(m.net/hours):'—']])}<p>Profit after recorded product and event costs, divided by all logged hours. This is not an hourly wage and does not deduct a separate value for your own time.</p><form id="timeForm" data-event="${e.id}"><div class="form-grid">${input(F('date','Date','date'))}${input(F('category','Activity','select','Production|Preparation|Travel|Setup|Selling|Pack-down'))}${input(F('hours','Hours','number'))}${input(F('notes','Notes'))}</div><p class="form-error" role="alert"></p><button class="secondary">Add time</button></form><div class="time-list">${logs.map(t=>`<div>${esc(t.date)} · ${esc(t.category)} <b>${t.hours} h</b>${btn('Delete','delete-time','text danger',`data-id="${t.id}"`)}</div>`).join('')}</div></article></div><article class="panel space"><h3>Closing history</h3><p>Saved snapshots stay unchanged when later sales or refunds are added. Save a new snapshot after corrections.</p><div class="table-wrap"><table><thead><tr><th>Day / saved</th><th>Opening</th><th>Sales</th><th>Refunds</th><th>Paid out</th><th>Expected</th><th>Counted</th><th>Difference</th></tr></thead><tbody>${db.closings.filter(c=>c.event===e.id).slice().reverse().map(c=>`<tr><td>${esc(c.date)}<small>${esc(new Date(c.createdAt).toLocaleString('en-US'))}</small>${esc(c.notes)}</td>${['opening','sales','refunds','paidOut','expected','counted','difference'].map(k=>`<td>${money(c[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></article>`;
}
function breakResult(e,b){const r=breakEven(db,e,Number(b.price),Number(b.cost),Number(b.feePercent),Number(b.feeFixed));return `<strong>${r.units===null?'No break-even at this price':r.units+' units to break even'}</strong><span>${money(r.fixed)} fixed costs · ${money(r.contribution)} contribution per item</span>`}
function cashResult(id,c){const r=cashSummary(db,id,c.date,Number(c.opening),Number(c.paidOut),Number(c.counted));return `<span>Cash sales ${money(r.sales)} · Cash refunds ${money(r.refunds)}</span><strong>Expected ${money(r.expected)}</strong><span>Drawer difference: <b>${money(r.difference)}</b> (${r.difference===0?'balanced':r.difference>0?'over':'short'})</span>`}
function returnEditor(id){const s=db.sales.find(s=>s.id===id);modal(`<form id="returnForm"><div class="modal-head"><h2>Return items</h2>${btn('×','close','icon','type="button" aria-label="Close"')}</div><p>The original sale stays in history. Refunds use the original price after its proportional discount.</p><label>Sale line<select name="line">${s.lines.map((l,i)=>`<option value="${i}">${esc(l.name)} · ${l.qty-db.returns.filter(r=>r.sale===id&&r.line===i).reduce((a,r)=>a+r.qty,0)} returnable</option>`).join('')}</select></label><div class="form-grid">${[F('date','Return date','date'),F('qty','Quantity','number'),F('payment','Refund method','select','Cash|Card|Venmo|PayPal|Bank Transfer|Other'),F('restock','Return to sellable stock','checkbox'),F('reason','Reason','textarea')].map(f=>input(f,{date:today(),qty:1,payment:s.payment,restock:true})).join('')}</div><p id="refundPreview"></p><p class="form-error" role="alert"></p><footer><button class="primary">Record return</button></footer></form>`);const update=()=>{const f=new FormData($('#returnForm'));$('#refundPreview').textContent='Estimated refund '+money(refundValue(s,Number(f.get('line')),Number(f.get('qty'))))};$('#returnForm').oninput=update;update();$('#returnForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);addReturn(db,{sale:id,line:Number(f.get('line')),qty:Number(f.get('qty')),date:f.get('date'),payment:f.get('payment'),restock:f.has('restock'),reason:f.get('reason')});save();$('#modal').close();render();toast('Return recorded. Original sale preserved.')}catch(err){$('.form-error').textContent=err.message}}}
function stockHistory(){const events=[...db.movements.map(m=>({...m,label:name('products',m.product),type:m.reason})),...db.sales.flatMap(s=>s.lines.flatMap(l=>(l.components||components(db,db.products.find(p=>p.id===l.product))).map(c=>({id:s.id,date:s.date,label:name('products',c.product),delta:-l.qty*c.qty,type:'Sale · '+l.name})))),...db.returns.flatMap(r=>{const l=db.sales.find(s=>s.id===r.sale)?.lines[r.line];return l?(l.components||components(db,db.products.find(p=>p.id===l.product))).map(c=>({date:r.date,label:name('products',c.product),delta:r.restock?r.qty*c.qty:0,type:r.restock?'Return to stock':'Return · not restocked',notes:r.reason})):[]})].filter(r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="toolbar"><input id="search" aria-label="Search history" placeholder="Search all stock history" value="${esc(query)}">${btn('Record stock movement','movement','primary')}</div><p>History starts with your saved opening stock. Sales, production, gifts, samples, damage and count corrections explain every change.</p><div class="panel table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Reason</th><th>Change</th><th>Note</th></tr></thead><tbody>${events.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.label)}</td><td>${esc(r.type)}</td><td>${r.delta>0?'+':''}${r.delta}</td><td>${esc(r.notes||'')}</td></tr>`).join('')}</tbody></table>${events.length?'':'<p>No movements recorded yet.</p>'}</div>`}
function movementEditor(id,qty){modal(`<form id="movementForm"><h2>Record a stock movement</h2><div class="form-grid"><label>Product<select name="product">${db.products.filter(p=>p.kind!=='Set').map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)} · ${stock(db,p)} available</option>`).join('')}</select></label>${input(F('date','Date','date'))}${input(F('reason','Reason','select','Production|Damage|Sample|Gift|Count correction'),{reason:id?'Production':'Damage'})}${input(F('quantity','Quantity (count correction: counted total)','number'),{quantity:qty||1})}${input(F('notes','Notes','textarea'))}</div><p class="form-error" role="alert"></p><footer><button class="primary">Save movement</button></footer></form>`);$('#movementForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),p=db.products.find(p=>p.id===f.get('product')),q=Number(f.get('quantity')),reason=f.get('reason');if(!p||!Number.isInteger(q)||q<0||reason!=='Count correction'&&q===0)throw Error('Choose a product and a valid whole quantity.');const delta=reason==='Count correction'?q-physical(db,p):reason==='Production'?q:-q;if(physical(db,p)+delta<0)throw Error('This movement would make stock negative.');db.movements.push({id:uid(),product:p.id,date:f.get('date'),reason,delta,notes:f.get('notes'),createdAt:new Date().toISOString()});save();$('#modal').close();render();toast('Stock movement recorded')}catch(err){$('.form-error').textContent=err.message}}}
function ordersView(){const rows=db.orders.filter(r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));return `<div class="toolbar"><input id="search" aria-label="Search orders" placeholder="Search customer, order or specification" value="${esc(query)}">${btn('New custom order','order','primary')}</div>${kpis([['Open orders',db.orders.filter(o=>!['Delivered','Cancelled'].includes(o.status)).length],['Outstanding balance',money(db.orders.filter(o=>o.status!=='Cancelled').reduce((a,o)=>a+o.total-o.deposit,0))]])}<p>Deposits are tracked here, separately from sales revenue and the market cash drawer. When an order is fulfilled, record its sale once for profit reporting.</p><div class="cards">${rows.map(o=>`<article class="panel"><span class="badge">${esc(o.status)}</span><h3>${esc(o.name)}</h3><p>${esc(o.customer)} · Due ${esc(o.due||'Not set')}</p><p class="prewrap">${esc(o.specification)}</p><div class="product-metrics"><div><small>Total</small><b>${money(o.total)}</b></div><div><small>Paid</small><b>${money(o.deposit)}</b></div><div><small>Remaining</small><b>${money(o.total-o.deposit)}</b></div></div>${btn('Edit order','order','secondary',`data-id="${o.id}"`)}</article>`).join('')||empty('Your custom orders will live here.')}</div>`}
function orderEditor(id){const old=db.orders.find(o=>o.id===id),fields=[F('name','Order name'),F('customer','Customer name'),F('contact','Customer contact'),F('specification','Color, size and requested details','textarea'),F('due','Delivery date','date'),F('total','Total price','number'),F('deposit','Total paid, including deposit','number'),F('status','Status','select','Requested|Confirmed|Making|Ready|Delivered|Cancelled'),F('notes','Notes / payment references','textarea')];modal(`<form id="orderForm"><div class="modal-head"><h2>${id?'Edit custom order':'New custom order'}</h2>${btn('×','close','icon','type="button" aria-label="Close"')}</div><div class="form-grid">${fields.map(f=>input(f,old||{})).join('')}</div><p id="orderBalance"></p><p class="form-error" role="alert"></p><footer><button class="primary">Save order</button></footer></form>`);$('#orderForm').oninput=()=>{const f=new FormData($('#orderForm'));$('#orderBalance').textContent='Remaining '+money(Number(f.get('total'))-Number(f.get('deposit')))};$('#orderForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),v={...old,id:id||uid()};for(const field of fields)v[field.key]=field.type==='number'?Number(f.get(field.key)||0):f.get(field.key);if(v.deposit>v.total)throw Error('Paid amount cannot exceed the order total.');if(!v.customer.trim())throw Error('Enter the customer name.');if(id)db.orders=db.orders.map(o=>o.id===id?v:o);else db.orders.push(v);save();$('#modal').close();render();toast('Custom order saved')}catch(err){$('.form-error').textContent=err.message}}}
function themeValues(){const t=themes[db.settings.theme]||themes['Olive Atelier'];return {main:db.settings.main||t[0],accent:db.settings.accent||t[2],background:db.settings.background||t[1],interfaceFont:'Arial',headingFont:'Georgia',handwriting:'Kalam',coverage:'Accents',night:false,calm:false,...db.settings}}
function inkOn(hex){const c=hex.replace('#',''),rgb=[0,2,4].map(i=>parseInt(c.slice(i,i+2),16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.179?'#20221f':'#ffffff'}
function applyTheme(){if(demoImages(db))save();const s=themeValues(),root=document.documentElement,vars={...themeColors(s),'--data-font':`"${s.interfaceFont}",Arial,sans-serif`,'--heading-font':`"${s.headingFont}",Georgia,serif`,'--hand-font':`"${s.handwriting}",cursive`};for(const [k,v]of Object.entries(vars))root.style.setProperty(k,v);document.body.dataset.coverage=s.coverage;document.body.classList.toggle('night',s.night);document.body.classList.toggle('calm',s.calm);document.body.classList.toggle('dark-surface',s.night||inkOn(s.background)==='#ffffff');document.querySelector('meta[name="theme-color"]').content=vars['--bg'];document.querySelectorAll('[data-theme]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.theme===s.theme)));}

function themeStudio(){const s=themeValues();return `<div class="theme-introduction"><p class="eyebrow">COLOR, THROUGHOUT YOUR STUDIO</p><h2>Make this space feel like you.</h2><p>One palette dresses the entire workspace. Fine-tune it your way.</p></div><div class="palette-grid">${Object.entries(themes).map(([n,c])=>`<button class="palette-option" data-action="theme" data-theme="${n}" aria-pressed="${db.settings.theme===n}" style="--sample-main:${c[0]};--sample-bg:${c[1]};--sample-accent:${c[2]}"><div class="palette-scene" aria-hidden="true"><i class="palette-sidebar"></i><div><i class="palette-title"></i><div class="palette-panels"><i></i><i></i></div><i class="palette-footer"></i></div></div><div class="palette-caption"><strong>${n}</strong><span class="palette-selected">✓</span></div></button>`).join('')}</div><div class="theme-workbench"><form id="appearanceForm" class="panel"><p class="eyebrow">YOUR PERSONAL PALETTE</p><h2>The finishing touches.</h2><div class="color-editors">${[['main','Main color','Menu, headings & buttons'],['accent','Accent color','Highlights & soft surfaces'],['background','Background','Your workspace canvas']].map(([k,label,note])=>`<fieldset><legend>${label}</legend><input aria-label="${label}" type="color" name="${k}" value="${s[k]}"><small>${note}</small><label>HEX<input data-hex="${k}" value="${s[k]}" pattern="#[0-9a-fA-F]{6}" maxlength="7"></label></fieldset>`).join('')}</div><div class="form-grid">${input(F('interfaceFont','Interface font','select','Arial|Verdana|Trebuchet MS|Georgia'),s)}${input(F('headingFont','Heading font','select','Georgia|Arial|Verdana|Trebuchet MS'),s)}${input(F('handwriting','Handwriting accent','select','Kalam|Caveat|Patrick Hand|Dancing Script|Sacramento'),s)}${input(F('coverage','Handwriting coverage','select','Accents|Headings|Full Look'),s)}${input(F('night','Night Mode','checkbox'),s)}${input(F('calm','Extra Calm Mode','checkbox'),s)}</div><p class="chart-note">Saved as you go. The gold A remains original. Forms and money stay easy to read.</p></form><article class="panel theme-preview"><span class="eyebrow">LIVE PREVIEW</span><h2>A little room to create.</h2><div class="preview-business">${esc(db.settings.businessName==='Your maker business'?'Your business name':db.settings.businessName)}</div><div class="preview-sample"><span class="badge">Ready for market</span><h3>Your next good thing.</h3><div class="preview-sample-lines" aria-hidden="true"><i></i><i></i><i></i></div></div><p class="hand-note">Made by you.<br>Organized, your way.</p>${btn('Explore market tools','nav','primary','data-page="market-tools"')}<p class="tiny">Appearance preview · no sample figures added to your records.</p></article></div>`}

function brandAll(){document.querySelectorAll('.brand').forEach(el=>{if(el.querySelector('img'))return;el.innerHTML=`<img src="./logo-a.svg" alt="AurelyStudio logo" class="official-logo"><span>AurelyStudio<small>Craft Fair Vendor OS</small></span>`});const crumb=$('.app-top>span');if(crumb)crumb.innerHTML=`${icon(eventId?'Events':titleOf(page),18)} <span>${esc(eventId?'Event workspace':titleOf(page))}</span>`}
function printStudio(){const p={mode:'Price cards',paper:'A4',ink:false,from:'',to:'',shopURL:'',...db.settings.print};return `<form id="printControls" class="panel"><div class="form-grid">${input(F('mode','Output','select','Price cards|Care cards|Shop QR sign|Market report'),p)}${input(F('paper','Paper','select','A4|Letter'),p)}${input(F('from','From','date'),p)}${input(F('to','To','date'),p)}${input(F('shopURL','Your shop URL','url'),p)}${input(F('ink','Ink saver','checkbox'),p)}</div><details open><summary>Include products / report sections</summary><div class="print-selection">${db.products.map(x=>`<label><input type="checkbox" data-print-product="${x.id}" ${!p.products||p.products.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}${['Summary','Sales','Expenses','Stock'].map(k=>`<label><input type="checkbox" data-print-section="${k}" ${!p.sections||p.sections.includes(k)?'checked':''}>${k}</label>`).join('')}</div></details><p class="form-error" role="alert"></p><button type="button" class="primary" id="printNow">Print / Save as PDF</button><p>Preview uses your saved records. QR codes are created on this device. Select your paper size in the browser print dialog too.</p></form><div class="print-preview-wrap"><div id="printPreview">${printContent(p)}</div></div>`}
function printContent(p){const products=db.products.filter(x=>!p.products||p.products.includes(x.id)),head=`<header class="print-brand"><img src="logo-a.svg" alt="AurelyStudio logo"><div><b>AurelyStudio</b><small>Craft Fair Vendor OS</small></div></header>`;let content='';if(p.mode==='Price cards'||p.mode==='Care cards')content=`<div class="print-cards">${products.map(x=>`<article>${head}<small>${esc(db.settings.businessName)}</small><h2>${esc(x.name)}</h2>${p.mode==='Price cards'?`<strong class="price-value">${money(x.price)}</strong><p>${esc(x.variant||x.category)}</p>`:`<p class="prewrap">${esc(x.care||'Add care instructions in this product’s details before printing.')}</p>`}</article>`).join('')}</div>`;if(p.mode==='Shop QR sign'){let qr='';try{const url=new URL(p.shopURL);if(!['https:','http:'].includes(url.protocol))throw Error();if(!window.qrcode)throw Error();const code=window.qrcode(0,'M');code.addData(url.href);code.make();qr=code.createSvgTag({cellSize:5,margin:20,scalable:true})}catch{qr='<p class="print-error">Enter a valid http or https shop URL to generate your QR sign.</p>'}content=`<article class="shop-sign">${head}<p>MADE WITH CARE</p><h1>${esc(db.settings.businessName)}</h1><div class="shop-qr">${qr}</div><h2>Find your next favorite.</h2><p>${esc(p.shopURL)}</p></article>`}if(p.mode==='Market report'){const m=metrics(db,'',p.from||'',p.to||'9999'),includes=k=>!p.sections||p.sections.includes(k),table=(head,rows)=>`<table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`,inRange=x=>(!p.from||x.date>=p.from)&&(!p.to||x.date<=p.to);content=head+`<h1>Market report</h1><p>${esc(p.from||'All history')} — ${esc(p.to||'Latest record')}</p>`+(includes('Summary')?kpis([['Revenue',money(m.revenue)],['Refunds',money(m.refunds)],['Total costs',money(m.cogs+m.expenses)],['Net profit',money(m.net)]]):'')+(includes('Sales')?'<h2>Sales</h2>'+table(['Date','Items','Payment','Total'],db.sales.filter(inRange).map(s=>[esc(s.date),esc(s.lines.map(l=>l.name+' ×'+l.qty).join(', ')),esc(s.payment),money(total(s))]))+'<h3>Refunds</h3>'+table(['Date','Reason','Amount'],db.returns.filter(inRange).map(r=>[esc(r.date),esc(r.reason),money(r.amount)])):'')+(includes('Expenses')?'<h2>Additional expenses</h2>'+table(['Date','Description','Amount'],db.expenses.filter(inRange).map(e=>[esc(e.date),esc(e.description),money(e.amount)]))+'<h3>Event setup costs</h3>'+table(['Date','Event','Setup costs'],db.events.filter(e=>inRange(e)&&e.status!=='Cancelled').map(e=>[esc(e.date),esc(e.name),money(costFields.reduce((a,k)=>a+Number(e[k]||0),0))])):'')+(includes('Stock')?'<h2>Current stock · snapshot today</h2>'+table(['Product','Available','Unit cost'],products.map(x=>[esc(x.name),stock(db,x),money(unitCost(db,x))])):'')}
 return `<section class="print-sheet ${p.ink?'ink-saver':''}" data-paper="${p.paper}">${content}<footer>AurelyStudio · Created ${esc(new Date().toLocaleString('en-US'))}</footer></section>`;
}
function bindExtra(){
 bindInsights();
 $('#insightEvent')?.addEventListener('change',e=>{db.settings.insightEvent=e.target.value;save();render()});
 $('#calendarJump')?.addEventListener('change',e=>{if(e.target.value){cal=new Date(e.target.value+'-01T12:00');render()}});
 $('#toolsEvent')?.addEventListener('change',e=>{db.settings.toolsEvent=e.target.value;if(eventId)eventId=e.target.value;save();render()});
 $('#breakForm')?.addEventListener('input',e=>{const f=new FormData(e.currentTarget),v=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)])),ev=db.events.find(x=>x.id===e.currentTarget.dataset.event);ev.breakEven=v;save();$('#breakResult').innerHTML=breakResult(ev,v)});
 $('#breakForm')?.addEventListener('submit',e=>e.preventDefault());
 const cash=$('#cashForm');if(cash){cash.oninput=()=>{$('#cashResult').innerHTML=cashResult(cash.dataset.event,Object.fromEntries(new FormData(cash)))};cash.onsubmit=e=>{e.preventDefault();const f=new FormData(cash),v={id:uid(),event:cash.dataset.event,date:f.get('date'),opening:Number(f.get('opening')),paidOut:Number(f.get('paidOut')),counted:Number(f.get('counted')),notes:f.get('notes'),createdAt:new Date().toISOString()};db.closings.push({...v,...cashSummary(db,v.event,v.date,v.opening,v.paidOut,v.counted)});save();render();toast('Closing snapshot saved')}}
 const tf=$('#timeForm');if(tf)tf.onsubmit=e=>{e.preventDefault();const f=new FormData(tf),hours=Number(f.get('hours'));if(hours<=0){tf.querySelector('.form-error').textContent='Enter more than zero hours.';return}db.timeLogs.push({id:uid(),event:tf.dataset.event,date:f.get('date'),category:f.get('category'),hours,notes:f.get('notes')});save();render();toast('Time added')};
 const af=$('#appearanceForm');if(af){af.onsubmit=e=>e.preventDefault();af.oninput=e=>{if(e.target.dataset.hex){if(!/^#[0-9a-f]{6}$/i.test(e.target.value))return;af.elements[e.target.dataset.hex].value=e.target.value}else if(e.target.type==='color')af.querySelector(`[data-hex="${e.target.name}"]`).value=e.target.value;const f=new FormData(af);Object.assign(db.settings,Object.fromEntries(f),{night:f.has('night'),calm:f.has('calm')});save();applyTheme()}};
 const pc=$('#printControls');if(pc){pc.onsubmit=e=>e.preventDefault();const refresh=()=>{const p=Object.fromEntries(new FormData(pc));p.ink=pc.elements.ink.checked;p.products=[...pc.querySelectorAll('[data-print-product]:checked')].map(x=>x.dataset.printProduct);p.sections=[...pc.querySelectorAll('[data-print-section]:checked')].map(x=>x.dataset.printSection);db.settings.print=p;save();$('#printPreview').innerHTML=printContent(p)};pc.oninput=refresh;$('#printNow').onclick=()=>{refresh();if($('#printPreview .print-error')){pc.querySelector('.form-error').textContent='Enter a valid shop URL first.';return}if(db.settings.print.from&&db.settings.print.to&&db.settings.print.from>db.settings.print.to){pc.querySelector('.form-error').textContent='The end date must be on or after the start date.';return}let st=$('#paperStyle');if(!st){st=document.createElement('style');st.id='paperStyle';document.head.append(st)}st.textContent=`@page { size: ${db.settings.print.paper==='Letter'?'letter':'A4'}; margin:12mm; }`;document.body.classList.add('printing-studio');window.print()}};
 if(page==='backup-data'){const controls=document.createElement('div');controls.className='quick-actions';controls.innerHTML=btn('Share backup','share-backup','secondary')+btn('Install app','install-app','secondary');$('.workspace').prepend(controls)}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='return')returnEditor(b.dataset.id);if(a==='order')orderEditor(b.dataset.id);if(a==='movement'||a==='produce')movementEditor(b.dataset.id,Number(b.dataset.qty));if(a==='delete-time'&&await ask('Delete this time entry?')){db.timeLogs=db.timeLogs.filter(t=>t.id!==b.dataset.id);save();render()}if(a==='add'&&b.dataset.kind==='allocations'&&!eventId&&page==='market-tools'){const ev=selectedEvent();const field=$('#recordForm [name=event]');if(field&&ev)field.value=ev.id}if(a==='share-backup'){const file=new File([JSON.stringify(db,null,2)],'AurelyStudio-Vendor-Backup-'+today()+'.json',{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]})}catch(err){if(err.name!=='AbortError')toast('Sharing failed. Use Export backup.')}}else document.querySelector('[data-action="export"]')?.click()}if(a==='install-app'){if(window.vendorInstall){await window.vendorInstall.prompt();window.vendorInstall=null}else modal(`<h2>Install Craft Fair Vendor OS</h2><p>iPhone / iPad: open in Safari → Share → Add to Home Screen.</p><p>Android / desktop: browser menu → Install app / Add to Home screen.</p><p>Installation requires HTTPS or localhost. Your records stay in this browser; export a backup before changing devices.</p>${btn('Done','close','primary')}`)}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.vendorInstall=e});window.addEventListener('afterprint',()=>document.body.classList.remove('printing-studio'));

function entryRoute(){const route=location.hash.slice(1);if(!route||route==='welcome'){history.replaceState(null,'',location.pathname+location.search+'#dashboard');return 'dashboard'}return route}

function businessNameEditor(){
 const current=db.settings.businessName==='Your maker business'?'':db.settings.businessName||'';
 modal(`<form id="businessNameForm"><div class="modal-head"><h2>Your business name</h2>${btn('×','close','icon','type="button" aria-label="Close"')}</div><p>This name appears below AurelyStudio and on your business documents.</p><label>Business name<input name="businessName" autocomplete="organization" maxlength="80" required placeholder="Your shop or studio name" value="${esc(current)}"></label><p class="form-error" role="alert"></p><footer>${btn('Cancel','close','secondary','type="button"')}<button class="primary" type="submit">Save name</button></footer></form>`);
 $('#businessNameForm input').focus();
 $('#businessNameForm').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('businessName').trim();if(!value){$('#businessNameForm .form-error').textContent='Enter your business name.';return}const previous=db.settings.businessName;db.settings.businessName=value;if(!save()){db.settings.businessName=previous;return}$('#modal').close();render();toast('Business name saved');$('.business-name')?.focus({preventScroll:true})};
}
